mapper.select:
SELECT ct.*, cls.class_name className, cls.class_course_id courseId, course.course_name FROM bd_class_time ct LEFT JOIN bd_class cls ON ct.class_id = cls.id LEFT JOIN bd_course course ON cls.class_course_id = course.id
cls.class_state = 0 and cls.is_delete = 0 and ct.is_delete = 0 #查询校区课表的条件
and ct.mec_id = #{mecId}
and ct.campus_id = #{campusId}
# 查询哪一天的条件
and ct.week_day = #{weekday}
# 模糊查询
and cls.class_name like CONCAT('%',#{className},'%')
and course.course_name like CONCAT('%',#{courseName},'%')
and ct.class_id = #{classId}
ORDER BY ct.week_day ASC, ct.cls_end_time ASC

SELECT ct.*, cls.class_name className, cls.class_course_id courseId, course.course_name , bis.`name` bishop_teacher_name, help.`name` help_teacher_name , cls.sum_students sum_students , cls.exist_students exist_students , course.color course_color FROM bd_class_time ct LEFT JOIN bd_class cls ON ct.class_id = cls.id LEFT JOIN bd_course course ON cls.class_course_id = course.id LEFT JOIN bd_teacher bis ON cls.bishop_teacher_id = bis.id LEFT JOIN bd_teacher help ON cls.help_teacher_id = help.id
cls.class_state = 0 and cls.is_delete = 0 and ct.is_delete = 0 and ct.mec_id = #{mecId} and ct.campus_id = #{campusId}
and ct.week_day in
#{day}
and ct.class_id = #{classId}
and cls.class_name like CONCAT('%',#{className},'%')
and course.course_name like CONCAT('%',#{courseName},'%')
ORDER BY ct.week_day ASC, ct.cls_end_time ASC
